function pickString(payload, key, defaultVal) {
  if (!payload || !Object.prototype.hasOwnProperty.call(payload, key)) {
    return defaultVal;
  }
  const v = payload[key];
  if (v === null || v === undefined) return defaultVal;
  return String(v);
}

